//! PII detection accuracy against the labelled corpus in `tests/pii/`
//! (generated by `tests/pii/gen_corpus.py`, fixed seed).
//!
//! Each sample is placed in the `L7Message` field the agent would carry it
//! in and run through `PiiEngine::scan_message` with the default config,
//! the same call `event_loop::handle_messages` makes. Reports per-type
//! precision / recall / F1, the share of clean payloads with any finding,
//! and a redaction check (no labelled value may survive in the field).
//!
//! `cargo test -p panopticon-agent pii_accuracy -- --nocapture` prints the
//! table; `PII_ACCURACY_VERBOSE=1` also prints false positives and misses.

use std::collections::BTreeMap;

use panopticon_common::Direction;

use super::{PiiEngine, is_credential_header, percent_decode};
use crate::config::PiiConfig;
use crate::protocol::{L7Message, Protocol};

#[derive(serde::Deserialize)]
struct Label {
    #[serde(rename = "type")]
    kind: String,
    start: usize,
    end: usize,
}

#[derive(serde::Deserialize)]
struct Sample {
    id: u64,
    field: String,
    header: Option<String>,
    text: String,
    labels: Vec<Label>,
}

/// Corpus label type for a detected category (phone sub-types are one
/// family in the corpus).
fn label_of(category: super::PiiCategory) -> String {
    let s = category.to_string();
    if s.starts_with("PHONE") {
        "PHONE".into()
    } else {
        s
    }
}

#[derive(Default)]
struct Counts {
    tp: usize,
    fp: usize,
    fn_: usize,
}

pub(crate) struct Score {
    per_type: BTreeMap<String, Counts>,
    clean: usize,
    clean_flagged: usize,
    labelled_values: usize,
    survivors: usize,
}

impl Score {
    fn get(&self, t: &str) -> (f64, f64, f64) {
        let c = &self.per_type[t];
        let p = if c.tp + c.fp == 0 {
            1.0
        } else {
            c.tp as f64 / (c.tp + c.fp) as f64
        };
        let r = if c.tp + c.fn_ == 0 {
            1.0
        } else {
            c.tp as f64 / (c.tp + c.fn_) as f64
        };
        let f = if p + r == 0.0 {
            0.0
        } else {
            2.0 * p * r / (p + r)
        };
        (p, r, f)
    }

    fn fpr(&self) -> f64 {
        self.clean_flagged as f64 / self.clean as f64
    }

    fn print(&self) {
        println!("| Type | Labels | TP | FP | FN | Precision | Recall | F1 |");
        println!("|---|---|---|---|---|---|---|---|");
        for (t, c) in &self.per_type {
            let (p, r, f) = self.get(t);
            let p = if c.tp + c.fp == 0 {
                "—".into()
            } else {
                format!("{p:.3}")
            };
            println!(
                "| {t} | {} | {} | {} | {} | {p} | {r:.3} | {f:.3} |",
                c.tp + c.fn_,
                c.tp,
                c.fp,
                c.fn_,
            );
        }
        println!(
            "clean payloads with a finding: {}/{} ({:.2}%)",
            self.clean_flagged,
            self.clean,
            100.0 * self.fpr()
        );
        println!(
            "labelled values surviving redaction: {}/{}",
            self.survivors, self.labelled_values
        );
    }
}

fn snippet(text: &str, start: usize, end: usize) -> String {
    let lo = text.floor_char_boundary(start.saturating_sub(30));
    let hi = text.ceil_char_boundary((end + 30).min(text.len()));
    format!(
        "{}[{}]{}",
        &text[lo..start],
        &text[start..end],
        &text[end..hi]
    )
}

pub(crate) fn score_corpus() -> Score {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../tests/pii/corpus.jsonl");
    let corpus = std::fs::read_to_string(path).expect("tests/pii/corpus.jsonl");
    let verbose = std::env::var_os("PII_ACCURACY_VERBOSE").is_some();
    let engine = PiiEngine::new(&PiiConfig::default(), &[]);

    let mut s = Score {
        per_type: BTreeMap::new(),
        clean: 0,
        clean_flagged: 0,
        labelled_values: 0,
        survivors: 0,
    };

    for line in corpus.lines() {
        let sample: Sample = serde_json::from_str(line).expect("corpus line");
        let mut msg = L7Message::new(Protocol::Http1, Direction::Ingress, 1);
        // The text the agent scans, which label offsets refer to.
        let scanned = match sample.field.as_str() {
            "path" => {
                msg.path = Some(sample.text.clone());
                percent_decode(&sample.text)
            }
            "header" => {
                let name = sample.header.clone().expect("header name");
                msg.headers = vec![(name, sample.text.clone())];
                sample.text.clone()
            }
            "request_text" => {
                msg.request_text = Some(sample.text.clone());
                sample.text.clone()
            }
            "payload_text" => {
                msg.payload_text = Some(sample.text.clone());
                sample.text.clone()
            }
            f => panic!("unknown field {f}"),
        };
        let report = engine.scan_message(&mut msg);
        let after = msg
            .path
            .or(msg.request_text)
            .or(msg.payload_text)
            .or(msg.headers.pop().map(|(_, v)| v))
            .unwrap_or_default();

        // Redaction check: every labelled value is gone from the field.
        for l in &sample.labels {
            s.labelled_values += 1;
            let value = &scanned[l.start..l.end];
            if after.contains(value) {
                s.survivors += 1;
                if verbose {
                    println!("SURVIVES {} #{}: {value}", l.kind, sample.id);
                }
            }
        }

        // Credential headers are masked wholesale without detection; they
        // count for the redaction check only.
        if sample.field == "header"
            && is_credential_header(sample.header.as_deref().unwrap_or_default())
        {
            continue;
        }

        let dets: Vec<(String, usize, usize)> = report
            .iter()
            .flat_map(|r| r.entities.iter())
            .map(|e| (label_of(e.category), e.start, e.end))
            .collect();
        if sample.labels.is_empty() {
            s.clean += 1;
            if !dets.is_empty() {
                s.clean_flagged += 1;
            }
        }
        let overlaps = |a: usize, b: usize, c: usize, d: usize| a < d && c < b;
        for l in &sample.labels {
            let hit = dets
                .iter()
                .any(|(t, a, b)| *t == l.kind && overlaps(*a, *b, l.start, l.end));
            let c = s.per_type.entry(l.kind.clone()).or_default();
            if hit {
                c.tp += 1;
            } else {
                c.fn_ += 1;
                if verbose {
                    println!(
                        "MISS {} #{}: {}",
                        l.kind,
                        sample.id,
                        snippet(&scanned, l.start, l.end)
                    );
                }
            }
        }
        for (t, a, b) in &dets {
            let ok = sample
                .labels
                .iter()
                .any(|l| l.kind == *t && overlaps(*a, *b, l.start, l.end));
            if !ok {
                s.per_type.entry(t.clone()).or_default().fp += 1;
                if verbose {
                    println!("FP {t} #{}: {}", sample.id, snippet(&scanned, *a, *b));
                }
            }
        }
    }
    s
}

#[test]
fn pii_accuracy() {
    let s = score_corpus();
    s.print();
}
